// Um jogo está revelado se o horário de início já passou
function isGameRevealed(game) {
  if (!game.kickoff) return false;
  return Date.now() >= game.kickoff;
}

// O painel revela se ALGUM jogo aberto já iniciou
function shouldRevealBets(games) {
  return games.some(g => isGameRevealed(g));
}

function loadFromStorage(key, fallback) {
  try { const r = localStorage.getItem(key); return r ? JSON.parse(r) : fallback; }
  catch { return fallback; }
}
function saveToStorage(key, data) {
  try { localStorage.setItem(key, JSON.stringify(data)); } catch {}
}
function generateId() { return Math.random().toString(36).substr(2, 9); }

// ── Garante que só os 3 jogos oficiais existam ──────────────────────────────
const OFFICIAL_IDS = ["g1", "g2", "g3"];
function loadGames() {
  // Sempre retorna apenas os 3 jogos oficiais do DEFAULT_GAMES,
  // mas preserva resultados (homeScore/awayScore) se já foram cadastrados
  try {
    const saved = JSON.parse(localStorage.getItem(STORAGE_KEY_GAMES) || "[]");
    return DEFAULT_GAMES.map(def => {
      const existing = saved.find(s => s.id === def.id);
      return existing ? { ...def, homeScore: existing.homeScore, awayScore: existing.awayScore } : def;
    });
  } catch { return DEFAULT_GAMES; }
}

// ── Lógica de visibilidade dos jogos por data ───────────────────────────────
// Jogo 1 (g1): visível sempre até 13/06; some a partir de 14/06
// Jogo 2 (g2): aparece esmaecido até 13/06, disponível a partir de 14/06; some a partir de 20/06
// Jogo 3 (g3): aparece esmaecido até 19/06, disponível a partir de 20/06
const GAME_RULES = {
  g1: { openFrom: null,          hideFrom: new Date("2026-06-14T00:00:00-03:00") },
  g2: { openFrom: new Date("2026-06-14T00:00:00-03:00"), hideFrom: new Date("2026-06-20T00:00:00-03:00") },
  g3: { openFrom: new Date("2026-06-20T00:00:00-03:00"), hideFrom: null },
};
function getGameStatus(gameId) {
  const now = new Date();
  const rule = GAME_RULES[gameId];
  if (!rule) return "open";
  if (rule.hideFrom && now >= rule.hideFrom) return "hidden";
  if (rule.openFrom && now < rule.openFrom) return "locked";
  return "open";
}

function isBrasilLosing(game, homeScore, awayScore) {
  if (homeScore === undefined || awayScore === undefined) return false;
  const brasilIsHome = game.home === "Brasil";
  const brasilIsAway = game.away === "Brasil";
  if (!brasilIsHome && !brasilIsAway) return false;
  if (brasilIsHome && awayScore > homeScore) return true;
  if (brasilIsAway && homeScore > awayScore) return true;
  return false;
}

// ─── ScoreInput ───────────────────────────────────────────────────────────────
function ScoreInput({ value, onChange, disabled, fullWidth }) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 6, width: fullWidth ? "100%" : "auto" }}>
      {[0,1,2,3,4,5].map(n => (
        <button key={n} onClick={() => !disabled && onChange(n)}
          style={{
            flex: fullWidth ? 1 : "none",
            width: fullWidth ? undefined : 40,
            height: 44, borderRadius: 10,
            background: value === n ? "#1B5E20" : "#F0F7F0",
            border: value === n ? "2.5px solid #1B5E20" : "1.5px solid #C8DEC8",
            color: value === n ? "#FACC15" : "#166534",
            fontFamily: "'Poppins', sans-serif",
            fontWeight: 800, fontSize: 17,
            cursor: disabled ? "default" : "pointer",
            transition: "all 0.12s", opacity: disabled ? 0.5 : 1,
          }}>{n}</button>
      ))}
    </div>
  );
}

function Badge({ children, color = "#C9A84C" }) {
  return (
    <span style={{
      display: "inline-block", padding: "2px 10px", borderRadius: 20,
      fontSize: 11, fontWeight: 700, letterSpacing: 1,
      background: color + "22", color, border: `1px solid ${color}55`,
      textTransform: "uppercase",
    }}>{children}</span>
  );
}

